\subsection{Diminishing learning rate rule}

\begin{assum}
\text{ } 

\begin{enumerate}
\item[{ (D1)}] For each $\bm{\theta} \in \mathbb{R}^\Theta$, the ordinary differential equation $\dot{\bm{w}}(t) = \nabla_{\bm{w}} \mathcal{L}_D (\bm{\theta}, \bm{w}(t))$ has a local asymptotically stable attractor $\lambda(\bm{\theta})$ within a domain of attraction such that $\lambda \colon \mathbb{R}^\Theta \to \mathbb{R}^W$ is Lipschitz continuous. The ordinary differential equation $\dot{\bm{\theta}}(t) = \nabla_{\bm{\theta}} \mathcal{L}_G (\bm{\theta}(t), \lambda(\bm{\theta}(t)))$ has a local asymptotically stable attractor $\bm{\theta}^*$ within a domain of attraction.
\item[{ {(D2)}}] $(a_n)_{n\in\mathbb{N}}$ and $(b_n)_{n\in\mathbb{N}}$ are monotone decreasing sequences satisfying either { (i)} or { (ii)}: 
\begin{enumerate}
\item[{ (i)}]
$\displaystyle{\sum_{n=0}^{+\infty} a_n = + \infty}$, 
$\displaystyle{\sum_{n=0}^{+\infty} a_n^2 < + \infty}$,
$\displaystyle{\sum_{n=0}^{+\infty} b_n = + \infty}$, 
$\displaystyle{\sum_{n=0}^{+\infty} b_n^2 < + \infty}$,
and 
$a_n = o (b_n)$;
\item[{ (ii)}]
$\displaystyle{\lim_{n \to + \infty} (n a_n)^{-1} = \lim_{n \to + \infty} (n b_n)^{-1} = 0}$
and 
$\displaystyle{\lim_{n \to + \infty} n^{-1} \sum_{k=0}^n a_k = \lim_{n \to + \infty} n^{-1} \sum_{k=0}^n b_k = 0}$.
\end{enumerate}
\item[{ {(D3)}}] $(\beta_n^D)_{n\in\mathbb{N}}$ and $(\beta_n^G)_{n\in\mathbb{N}}$ satisfy that $\displaystyle{\lim_{n \to + \infty} n^{-1} \sum_{k=0}^n \beta_k^D = \lim_{n \to + \infty} n^{-1} \sum_{k=0}^n \beta_k^G = 0}$.
\end{enumerate}

\end{assum}
Assumption (D1) is the same as (A4) in [CITE:Heusel2017] (see also [CITE:BORKAR1997291]). {Assumption} (D2)(i) [CITE:Heusel2017] {is} needed to guarantee the almost-sure convergence of Algorithm [REF:algo:1], while Assumptions (D2)(ii) and {(D3)} are used to provide the rate of convergence of Algorithm [REF:algo:1].

The following presents a convergence analysis as well as a convergence rate analysis of Algorithm [REF:algo:1] with diminishing learning rates. 

\begin{thm}
Suppose that Assumptions [REF:assum:1](A1)--(A2) and [REF:const](C2)--{(C3)} hold. Then, the following hold:

{ (i)} { [Convergence]} Under Assumption [REF:dim](D1) {and} (D2)(i), the sequence $((\bm{\theta}_n, \bm{w}_n))_{n\in\mathbb{N}}$ generated by Algorithm [REF:algo:1] converges almost surely to a point $(\bm{\theta}^\star, \bm{w}^\star) \in \mathrm{LNE}(\mathcal{L}_D, \mathcal{L}_G)$.

\vspace{-1mm}
{ (ii)} { [Convergence Rate]} Under Assumption [REF:dim](D2)(ii) and {(D3)},
\begin{equation}
\begin{split}
&\frac{1}{N} \sum_{n\in [N]} \mathbb{E}\left[\left\langle \bm{\theta}_n - \bm{\theta}, 
\nabla_{\bm{\theta}} \mathcal{L}_G(\bm{\theta}_n, \bm{w}_n) \right\rangle \right]\\
&\leq \frac{C_1^2}{2 a_N N}
 + \frac{2 C_1 \tilde{K}_1}{N} \sum_{n\in [N]} \beta_n^{G}
+ 
\frac{2 \tilde{K}_1^2}{N} \sum_{n\in [N]} a_n,\\
&\frac{1}{N} \sum_{n\in [N]} \mathbb{E}\left[\left\langle \bm{w}_n - \bm{w}, 
\nabla_{\bm{w}} \mathcal{L}_D(\bm{\theta}_n, \bm{w}_n) \right\rangle \right] \\
&\leq
\frac{C_2^2}{2 b_N N}
+ \frac{2 C_2 \tilde{K}_2}{N} \sum_{n\in [N]} \beta_n^{D} 
+ 
\frac{2 \tilde{K}_2^2}{N} \sum_{n\in [N]} b_n.
\end{split}
\end{equation}
If we use $a_n = \mathcal{O}(n^{-\eta_a})$, $\beta_n^G = \mathcal{O}(n^{-\eta_a})$, $b_n = \mathcal{O}(n^{-\eta_b})$, and $\beta_n^D = \mathcal{O}(n^{-\eta_b})$, where $\eta_a, \eta_b \in (0,1)$, then 
\begin{equation}
\begin{split}
&\frac{1}{N} \sum_{n\in [N]} \mathbb{E}\left[\left\langle \bm{\theta}_n - \bm{\theta}, 
\nabla_{\bm{\theta}} \mathcal{L}_G(\bm{\theta}_n, \bm{w}_n) \right\rangle \right]
\leq 
\mathcal{O}\left( \frac{1}{N^{\mu_a}} \right), \\
&
\frac{1}{N} \sum_{n\in [N]} \mathbb{E}\left[\left\langle \bm{w}_n - \bm{w}, 
\nabla_{\bm{w}} \mathcal{L}_D(\bm{\theta}_n, \bm{w}_n) \right\rangle \right]
\leq
\mathcal{O}\left( \frac{1}{N^{\mu_b}} \right),
\end{split}
\end{equation}
where $\mu_a := \min\{ \eta_a, 1 - \eta_a \}$ and $\mu_b := \min\{ \eta_b, 1 - \eta_b \}$. {Let $a, b > 0$ and a rate $\gamma \in (0,1)$ that decays every $T$ iterations. If we use 
\begin{align}
\begin{split}
(a_n) 
&= (\underbrace{a,a,\ldots,a}_{T}, 
\underbrace{\gamma a, \gamma a, \ldots, \gamma a}_{T}, \ldots,\\
&\qquad \underbrace{\gamma^{P-1} a, \gamma^{P-1} a, \ldots, \gamma^{P-1} a}_{T}, \ldots),\\
(b_n) 
&= (\underbrace{b,b,\ldots,b}_{T}, 
\underbrace{\gamma b, \gamma b, \ldots, \gamma b}_{T}, \ldots,\\
&\qquad \underbrace{\gamma^{P-1} b, \gamma^{P-1} b, \ldots, \gamma^{P-1} b}_{T}, \ldots),
\end{split}
\end{align}
$\beta_n^G$ with $\sum_{n=0}^{+ \infty} \beta_n^G < + \infty$, and $\beta_n^D$ with $\sum_{n=0}^{+ \infty} \beta_n^D < + \infty$, then
\begin{align*}
&\frac{1}{N} \sum_{n\in [N]} \mathbb{E}\left[\left\langle \bm{\theta}_n - \bm{\theta}, 
\nabla_{\bm{\theta}} \mathcal{L}_G(\bm{\theta}_n, \bm{w}_n) \right\rangle \right]
\leq 
\mathcal{O}\left( \frac{1}{N} \right), \\
&
\frac{1}{N} \sum_{n\in [N]} \mathbb{E}\left[\left\langle \bm{w}_n - \bm{w}, 
\nabla_{\bm{w}} \mathcal{L}_D(\bm{\theta}_n, \bm{w}_n) \right\rangle \right]
\leq
\mathcal{O}\left( \frac{1}{N} \right),
\end{align*}
where $N = TP$.
}
\end{thm}

